// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 n, uint64 t, uint256 f, bytes32 h) internal {
        uint64 before;
        try c.number() returns (uint64 __r) { before = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(n, t, f, h, 0, bytes32(0), 0, 0) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted && c.number() == before);
    }

    function testFuzz_run(uint64 n, uint64 t, uint256 f, bytes32 h) public {
        _run(n, t, f, h);
    }

    receive() external payable {}
}
